/* =====================================================================
 * Mawe Tatu Dairy — growth.js (Calves tab → Growth, v5.9)
 * ---------------------------------------------------------------------
 * GENERATED by build_growth.py from src/growth.js.tpl + src/growth_model.js
 * (the growth model is shared with Growth.gs). Edit the src files and rebuild.
 *
 * 1. WEIGH DAY (#gw-form): pick the date and method, then type the weights of
 *    the animals weighed (young stock listed; "Include cows and bulls" shows
 *    the rest). Any date from the animal's birth to today is accepted, so old
 *    weights can be entered the same way. Each box shows the gain and ADG
 *    since the previous weight as you type; unlikely changes (a fall of more
 *    than 10%, or more than 2 kg/day up) ask "are you sure?".
 * 2. ANIMAL CARDS (#gw-animals): latest weight, age, ADG (latest, last 3
 *    months, since birth), target, flags. Tap a card for its history: a small
 *    chart and every weight with the gain, days and ADG since the one before,
 *    each with Edit.
 * 3. EDIT (#gw-edit): not uploaded → the phone's entry is changed or deleted;
 *    uploaded → the phone's copy changes at once and a correction is queued
 *    (Corrections.gs, sheet Calf_Weights, id = clientId) with a reason;
 *    Cancel = Status Void.
 *
 * Data: store `calf_weights` (append; kept, not pruned, so ADG works
 * offline); kv 'growthList' caches listGrowth (all phones' weights and the
 * birth weights from calving records). The sheet's copy wins for uploaded
 * weights, except where this phone has a newer correction or a cancellation.
 * Loaded before app.js; defines window.MaweGrowth.
 * ===================================================================== */

(() => {
  'use strict';

  /* ---- Growth model (shared: Growth.gs and growth.js are built from this file
   *      by build_growth.py — edit here, then rebuild). Plain functions, no
   *      browser or Apps Script calls, so it runs the same on the phone and in
   *      the sheet. ---- */

  /**
   * GRW_RULES — change to suit the farm.
   *   targetAdg     target average daily gain (kg/day) for young stock, by
   *                 breed; 'default' covers Friesian, Ayrshire, Fleckvieh and
   *                 crosses. Heifers growing at about these rates reach
   *                 breeding size at 15–18 months and calve at 24–27 months.
   *   slowShare     growth below this share of the target is flagged (0.8 → 80%).
   *   minDays       the shortest gap between two weights used for an ADG
   *                 (closer weights mostly measure gut fill and scale error).
   *   lossKg        a fall of more than this between weighings is flagged.
   *   weighEvery    young stock not weighed for more than this many days are flagged.
   *   youngMonths   animals are treated as young stock up to this age.
   *   doubleBy      calves should about double their birth weight by this age (days).
   *   recentDays    the window for "ADG over the last 3 months".
   */
  var GRW_RULES = {
    targetAdg: { Jersey: 0.5, 'default': 0.6 },
    slowShare: 0.8,
    minDays: 7,
    lossKg: 1,
    weighEvery: 35,
    youngMonths: 24,
    doubleBy: 56,
    recentDays: 90,
    minKg: 10,
    maxKg: 900,
  };

  /** Whole days from date key a to date key b ('YYYY-MM-DD'). */
  function grwDays(a, b) {
    var pa = String(a).split('-'), pb = String(b).split('-');
    return Math.round((Date.UTC(+pb[0], +pb[1] - 1, +pb[2]) - Date.UTC(+pa[0], +pa[1] - 1, +pa[2])) / 86400000);
  }

  function grwRound(x, dp) { var f = Math.pow(10, dp || 0); return Math.round(x * f) / f; }

  /** Target ADG (kg/day) for a breed name. */
  function grwTarget(breed) {
    var b = String(breed || '');
    return GRW_RULES.targetAdg[b] !== undefined ? GRW_RULES.targetAdg[b] : GRW_RULES.targetAdg['default'];
  }

  /**
   * One animal's weights, oldest first, one per day (the later-entered one wins
   * when two share a date), each with the gain since the previous weight.
   *   points: [{ date, kg, source ('weight' | 'birth'), id?, method?, createdAt? }]
   * Returns [{ date, kg, source, id, method, days, gain, adg }] — days / gain /
   * adg are null on the first weight; adg is null when the gap is under 1 day.
   */
  function grwSeries(points) {
    var byDate = {};
    (points || []).forEach(function (p) {
      if (!p || !p.date || !(Number(p.kg) > 0)) return;
      var cur = byDate[p.date];
      // A weighing beats a birth weight from the calving record on the same day;
      // among weighings, the later-entered one wins.
      if (!cur || (cur.source === 'birth' && p.source !== 'birth') ||
          (cur.source === p.source && String(p.createdAt || '') >= String(cur.createdAt || ''))) byDate[p.date] = p;
    });
    var dates = Object.keys(byDate).sort();
    var out = [];
    dates.forEach(function (d, i) {
      var p = byDate[d];
      var row = { date: d, kg: Number(p.kg), source: p.source || 'weight', id: p.id || '', method: p.method || '', days: null, gain: null, adg: null };
      if (i > 0) {
        var prev = out[i - 1];
        row.days = grwDays(prev.date, d);
        row.gain = grwRound(row.kg - prev.kg, 1);
        row.adg = row.days >= 1 ? grwRound((row.kg - prev.kg) / row.days, 3) : null;
      }
      out.push(row);
    });
    return out;
  }

  /** ADG between the latest weight and the latest earlier weight at least minDays before it. */
  function grwAdgLatest(series) {
    if (series.length < 2) return null;
    var last = series[series.length - 1];
    for (var i = series.length - 2; i >= 0; i--) {
      var d = grwDays(series[i].date, last.date);
      if (d >= GRW_RULES.minDays) return { adg: grwRound((last.kg - series[i].kg) / d, 3), days: d, from: series[i].date };
    }
    return null;
  }

  /**
   * Summary for one animal.
   *   animal: { animalId, name, dateOfBirth ('YYYY-MM-DD' | ''), breed, category, sex, status }
   *   points: as for grwSeries
   *   today:  'YYYY-MM-DD'
   * Returns { animalId, name, series, latest, ageDays (at today), ageMonths,
   *   birthKg, adgLatest {adg, days, from}, adgBirth, adgRecent {adg, days, from},
   *   target, flags: [{ code, text }], young, daysSince }
   */
  function grwSummary(animal, points, today) {
    var a = animal || {};
    var series = grwSeries(points);
    var dob = a.dateOfBirth || '';
    var latest = series.length ? series[series.length - 1] : null;
    var ageDays = dob ? grwDays(dob, today) : null;
    var out = {
      animalId: a.animalId, name: a.name || a.animalId, breed: a.breed || '', series: series, latest: latest,
      ageDays: ageDays, ageMonths: ageDays === null ? null : grwRound(ageDays / 30.44, 1),
      birthKg: null, adgLatest: grwAdgLatest(series), adgBirth: null, adgRecent: null,
      target: grwTarget(a.breed), flags: [], daysSince: latest ? grwDays(latest.date, today) : null,
      young: ageDays === null ? /^(Calf|Heifer)$/i.test(String(a.category || '')) : ageDays <= GRW_RULES.youngMonths * 30.44,
    };
    // Birth weight: a weight on the date of birth (or a calving-record weight).
    var birth = series.filter(function (s) { return s.source === 'birth' || (dob && s.date === dob); })[0] || null;
    if (birth) {
      out.birthKg = birth.kg;
      if (latest && latest !== birth) {
        var dB = grwDays(dob || birth.date, latest.date);
        if (dB >= GRW_RULES.minDays) out.adgBirth = grwRound((latest.kg - birth.kg) / dB, 3);
      }
    }
    // Recent: latest vs the earliest weight within recentDays before it (at least 21 days apart).
    if (latest) {
      for (var i = 0; i < series.length - 1; i++) {
        var d = grwDays(series[i].date, latest.date);
        if (d <= GRW_RULES.recentDays && d >= 21) { out.adgRecent = { adg: grwRound((latest.kg - series[i].kg) / d, 3), days: d, from: series[i].date }; break; }
      }
    }
    // Flags.
    var lastStep = series.length >= 2 ? series[series.length - 1] : null;
    if (lastStep && lastStep.gain !== null && lastStep.gain < -GRW_RULES.lossKg) {
      out.flags.push({ code: 'loss', text: 'Lost ' + grwRound(-lastStep.gain, 1) + ' kg since ' + series[series.length - 2].date });
    }
    var check = out.adgLatest;
    if (check && check.adg >= 0 && check.adg < out.target * GRW_RULES.slowShare && out.young) {
      out.flags.push({ code: 'slow', text: 'Growing ' + grwRound(check.adg, 2) + ' kg/day, below the target of ' + out.target + ' kg/day' });
    }
    // Early warning only while the calf is under about 13 weeks: the weight
    // nearest 8 weeks (49–91 days) should be about twice the birth weight.
    if (out.birthKg && dob && ageDays !== null && ageDays <= GRW_RULES.doubleBy + 35) {
      var w = null;
      series.forEach(function (s) {
        var g = grwDays(dob, s.date);
        if (g < GRW_RULES.doubleBy - 7 || g > GRW_RULES.doubleBy + 35) return;
        if (!w || Math.abs(g - GRW_RULES.doubleBy) < Math.abs(grwDays(dob, w.date) - GRW_RULES.doubleBy)) w = s;
      });
      if (w && w.kg < 2 * out.birthKg) out.flags.push({ code: 'double', text: 'Not yet double the birth weight (' + out.birthKg + ' kg) at ' + grwDays(dob, w.date) + ' days' });
    }
    if (out.young && a.status !== 'Sold' && a.status !== 'Dead') {
      if (!latest) out.flags.push({ code: 'due', text: 'Never weighed' });
      else if (out.daysSince > GRW_RULES.weighEvery) out.flags.push({ code: 'due', text: 'Last weighed ' + out.daysSince + ' days ago' });
    }
    return out;
  }

  /**
   * Checks a new weight against the animal's earlier ones: returns a warning
   * text when it implies an unlikely change (more than 2 kg/day up, or a fall of
   * more than 10%), else ''. Used to ask "are you sure?" before saving.
   */
  function grwCheckNew(points, date, kg) {
    var series = grwSeries(points).filter(function (s) { return s.date !== date; });
    var before = series.filter(function (s) { return s.date < date; });
    var prev = before.length ? before[before.length - 1] : null;
    if (!prev) return '';
    var d = grwDays(prev.date, date);
    if (kg < prev.kg * 0.9) return 'That is ' + grwRound(prev.kg - kg, 1) + ' kg less than on ' + prev.date + ' (' + prev.kg + ' kg).';
    if (d >= 1 && (kg - prev.kg) / d > 2) return 'That is a gain of ' + grwRound((kg - prev.kg) / d, 1) + ' kg/day since ' + prev.date + ' (' + prev.kg + ' kg).';
    return '';
  }

  const STORE = 'calf_weights';
  const PAYLOAD = Object.freeze({
    [STORE]: ['clientId', 'deviceId', 'date', 'animalId', 'animalName', 'weightKg', 'method', 'notes', 'recordedBy', 'createdAt'],
  });
  const METHODS = ['Weigh band', 'Scale', 'Estimate'];

  function create(deps) {
    const { db, SYNC_STATUS, getSession, getDeviceId, makeUUID, todayLocal, esc, toast, requestSync, saveDebounceMs, callServer, queueCorrection, isInFlight } = deps;
    const $ = (s) => document.querySelector(s);
    const $$ = (s) => [...document.querySelectorAll(s)];
    const show = (el, v) => el && el.classList.toggle('hidden', !v);
    const num = (v) => { const n = parseFloat(String(v ?? '').replace(/,/g, '')); return Number.isFinite(n) ? n : null; };
    const fmt = (k) => { const [y, m, d] = k.split('-').map(Number); return new Date(y, m - 1, d).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' }); };
    const kgs = (x) => `${grwRound(x, 1)} kg`;
    const adgTxt = (x) => (x === null || x === undefined ? '—' : `${grwRound(x, 2).toFixed(2)}`);
    const ageTxt = (days) => (days === null ? 'age unknown' : days < 60 ? `${days} days` : days < 730 ? `${grwRound(days / 30.44, 1)} months` : `${grwRound(days / 365.25, 1)} years`);

    let animals = [];
    let local = [];
    let server = null;     // { weights, births, rules, serverTime }
    let showAll = false;   // include cows and bulls in the weigh list
    let open = null;       // animalId of the expanded card
    let editing = null;    // the weight being edited (merged row)

    /* ================= data ================= */

    /** Every weight known to this phone: the sheet's copy, plus this phone's unsent, corrected or cancelled entries. */
    function weights() {
      const map = {};
      ((server && server.weights) || []).forEach((w) => { map[w.clientId] = { ...w, syncStatus: SYNC_STATUS.SYNCED, fromServer: true }; });
      local.forEach((l) => {
        if (l.voided) { delete map[l.clientId]; return; }
        const s = map[l.clientId];
        if (l.syncStatus !== SYNC_STATUS.SYNCED || !s || (l.corrected && String(l.updatedAt || '') > String(s.updatedAt || ''))) map[l.clientId] = { ...l };
      });
      return Object.values(map);
    }
    function pointsFor(id, all) {
      const pts = (all || weights()).filter((w) => w.animalId === id)
        .map((w) => ({ date: w.date, kg: Number(w.weightKg), source: 'weight', id: w.clientId, method: w.method, createdAt: w.createdAt }));
      ((server && server.births) || []).filter((b) => b.animalId === id).forEach((b) => pts.push({ date: b.date, kg: b.kg, source: 'birth', id: '', method: 'Calving record', createdAt: '' }));
      return pts;
    }
    const farm = () => animals.filter((a) => a.herd === 'farm' || /^MT-/.test(a.animalId));
    const byId = (id) => animals.find((a) => a.animalId === id);
    const isYoung = (a) => grwSummary(a, [], todayLocal()).young;
    function weighList() {
      return farm().filter((a) => a.status === 'Active' && (showAll || isYoung(a)))
        .sort((x, y) => String(y.dateOfBirth || '0').localeCompare(String(x.dateOfBirth || '0')) || x.animalId.localeCompare(y.animalId));
    }

    /* ================= view switch ================= */

    function setView(view) {
      $$('.cv-view-btn').forEach((b) => {
        const on = b.dataset.view === view;
        b.setAttribute('aria-pressed', String(on));
        b.classList.toggle('bg-calf-600', on); b.classList.toggle('text-white', on);
        b.classList.toggle('bg-white', !on); b.classList.toggle('text-calf-700', !on);
      });
      show($('#cv-view-feed'), view === 'feed');
      show($('#cv-view-growth'), view === 'growth');
      if (view === 'growth') { render(); refresh(false); }
    }

    /* ================= weigh day ================= */

    function renderWeighRows() {
      const date = $('#gw-date').value || todayLocal();
      const all = weights();
      const keep = {};
      $$('#gw-rows input[data-id]').forEach((i) => { if (i.value !== '') keep[i.dataset.id] = i.value; });
      const list = weighList();
      $('#gw-rows').innerHTML = list.length ? list.map((a) => {
        const s = grwSeries(pointsFor(a.animalId, all)).filter((p) => p.date < date);
        const prev = s.length ? s[s.length - 1] : null;
        const age = a.dateOfBirth ? grwDays(a.dateOfBirth, date) : null;
        return `<li class="flex items-center gap-3 py-2 border-t border-slate-100 first:border-0">
          <div class="flex-1 min-w-0">
            <p class="text-sm font-semibold truncate">${esc(a.name || a.animalId)} <span class="font-normal text-slate-400">${esc(a.animalId)}</span></p>
            <p class="text-xs text-slate-500">${age !== null && age < 0 ? '<span class="text-red-600">not born yet on this date</span>' : esc(ageTxt(age))}${prev ? ` · last ${kgs(prev.kg)} on ${esc(fmt(prev.date))}` : ' · no earlier weight'}</p>
            <p class="gw-hint text-xs" data-for="${esc(a.animalId)}"></p>
          </div>
          <input type="number" min="${GRW_RULES.minKg}" max="${GRW_RULES.maxKg}" step="0.1" inputmode="decimal" placeholder="kg" data-id="${esc(a.animalId)}"
            class="w-24 shrink-0 rounded-xl border border-slate-300 px-3 py-2.5 text-base text-right focus:outline-none focus:ring-2 focus:ring-calf-500" aria-label="Weight of ${esc(a.name || a.animalId)} in kg" ${age !== null && age < 0 ? 'disabled' : ''} />
        </li>`;
      }).join('') : `<li class="text-sm text-slate-400 py-2">${showAll ? 'No active animals in the herd register.' : 'No calves or heifers in the herd register. Tick "Include cows and bulls" to weigh others.'}</li>`;
      $$('#gw-rows input[data-id]').forEach((i) => { if (keep[i.dataset.id] !== undefined) i.value = keep[i.dataset.id]; });
      $$('#gw-rows input[data-id]').forEach(hint);
    }

    /** Gain and ADG since the previous weight, as the user types. */
    function hint(input) {
      const el = document.querySelector(`.gw-hint[data-for="${input.dataset.id}"]`);
      if (!el) return;
      const kg = num(input.value);
      const date = $('#gw-date').value || todayLocal();
      if (kg === null) { el.textContent = ''; return; }
      const s = grwSeries(pointsFor(input.dataset.id)).filter((p) => p.date < date);
      const prev = s.length ? s[s.length - 1] : null;
      const warn = grwCheckNew(pointsFor(input.dataset.id), date, kg);
      if (!prev) { el.className = 'gw-hint text-xs text-slate-500'; el.textContent = 'First weight on record.'; return; }
      const d = grwDays(prev.date, date);
      const g = kg - prev.kg;
      el.className = `gw-hint text-xs ${warn ? 'text-amber-800 font-semibold' : g < 0 ? 'text-red-700' : 'text-calf-700'}`;
      el.textContent = `${g >= 0 ? '+' : ''}${grwRound(g, 1)} kg in ${d} day${d === 1 ? '' : 's'}${d >= 1 ? ` = ${adgTxt(g / d)} kg/day` : ''}${warn ? ' — check this' : ''}`;
    }

    function setError(sel, m) { const el = $(sel); el.textContent = m || ''; show(el, !!m); }

    async function saveWeighDay(e) {
      e.preventDefault();
      setError('#gw-error', '');
      const s = getSession();
      if (!s) { toast('Sign in first', 'error'); return; }
      const date = $('#gw-date').value;
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date > todayLocal()) { setError('#gw-error', 'Pick the date (not in the future).'); return; }
      const method = $('#gw-method').value;
      const notes = $('#gw-notes').value.trim().slice(0, 300);
      const entries = [];
      const warns = [];
      const all = weights();
      for (const i of $$('#gw-rows input[data-id]')) {
        if (i.value.trim() === '') continue;
        const a = byId(i.dataset.id) || { animalId: i.dataset.id, name: i.dataset.id };
        const kg = num(i.value);
        if (kg === null || kg < GRW_RULES.minKg || kg > GRW_RULES.maxKg) { setError('#gw-error', `${a.name}: weight must be ${GRW_RULES.minKg}–${GRW_RULES.maxKg} kg.`); i.focus(); return; }
        if (a.dateOfBirth && date < a.dateOfBirth) { setError('#gw-error', `${a.name} was born on ${fmt(a.dateOfBirth)}: pick a later date.`); return; }
        const w = grwCheckNew(pointsFor(a.animalId, all), date, kg);
        if (w) warns.push(`${a.name}: ${w}`);
        if (all.some((x) => x.animalId === a.animalId && x.date === date)) warns.push(`${a.name} already has a weight on ${fmt(date)}: the new one will be used.`);
        entries.push({ a, kg });
      }
      if (!entries.length) { setError('#gw-error', 'Type at least one weight.'); return; }
      if (warns.length && !confirm(`Please check:\n\n${warns.join('\n')}\n\nSave anyway?`)) return;
      const now = new Date().toISOString();
      await db[STORE].bulkAdd(entries.map(({ a, kg }) => ({
        clientId: makeUUID(), deviceId: getDeviceId(), date, animalId: a.animalId, animalName: a.name || '', weightKg: grwRound(kg, 1), method, notes,
        recordedBy: s.email, createdAt: now, updatedAt: now, syncStatus: SYNC_STATUS.PENDING, syncAttempts: 0, lastError: null, syncedAt: null,
      })));
      $$('#gw-rows input[data-id]').forEach((i) => { i.value = ''; });
      $('#gw-notes').value = '';
      toast(`${entries.length} weight${entries.length === 1 ? '' : 's'} saved`);
      requestSync('new-record', saveDebounceMs);
    }

    /* ================= animal cards ================= */

    function chart(series, target, dob) {
      if (series.length < 2) return '';
      const W = 300, H = 90, P = 6;
      const x0 = series[0].date, span = Math.max(1, grwDays(x0, series[series.length - 1].date));
      const kgMin = Math.min(...series.map((p) => p.kg)), kgMax = Math.max(...series.map((p) => p.kg));
      const lo = Math.max(0, kgMin - 5), hi = kgMax + 5;
      const X = (d) => P + (grwDays(x0, d) / span) * (W - 2 * P);
      const Y = (kg) => H - P - ((kg - lo) / (hi - lo)) * (H - 2 * P);
      const line = series.map((p) => `${X(p.date).toFixed(1)},${Y(p.kg).toFixed(1)}`).join(' ');
      // Target line from the first weight at the target ADG.
      const t2 = Math.min(hi, series[0].kg + target * span);
      const tEnd = t2 >= hi ? x0 : series[series.length - 1].date;
      const tx2 = t2 >= hi ? P + ((hi - series[0].kg) / target / span) * (W - 2 * P) : X(tEnd);
      return `<svg viewBox="0 0 ${W} ${H}" class="w-full h-24 mt-2" role="img" aria-label="Weight over time">
        <line x1="${X(x0)}" y1="${Y(series[0].kg)}" x2="${tx2.toFixed(1)}" y2="${Y(t2).toFixed(1)}" stroke="#cbd5e1" stroke-dasharray="4 3" stroke-width="1.5"/>
        <polyline points="${line}" fill="none" stroke="#d97706" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>
        ${series.map((p) => `<circle cx="${X(p.date).toFixed(1)}" cy="${Y(p.kg).toFixed(1)}" r="3" fill="${p.source === 'birth' ? '#94a3b8' : '#b45309'}"/>`).join('')}
      </svg><p class="text-[10px] text-slate-400">Dashed: growth at the target of ${target} kg/day from the first weight.</p>`;
    }

    function render() {
      if (!$('#cv-view-growth')) return;
      renderWeighRows();
      const today = todayLocal();
      const all = weights();
      const withW = new Set(all.map((w) => w.animalId).concat(((server && server.births) || []).map((b) => b.animalId)));
      const list = farm().filter((a) => withW.has(a.animalId) || (a.status === 'Active' && isYoung(a)));
      const sums = list.map((a) => grwSummary(a, pointsFor(a.animalId, all), today))
        .sort((x, y) => (y.flags.length - x.flags.length) || String(byId(y.animalId)?.dateOfBirth || '').localeCompare(String(byId(x.animalId)?.dateOfBirth || '')));
      const flagged = sums.filter((s) => s.flags.some((f) => f.code !== 'due')).length;
      const due = sums.filter((s) => s.flags.some((f) => f.code === 'due')).length;
      $('#gw-summary').textContent = sums.length ? `${sums.length} animal${sums.length === 1 ? '' : 's'}${flagged ? ` · ${flagged} need attention` : ''}${due ? ` · ${due} due for weighing` : ''}` : '';
      $('#gw-animals').innerHTML = sums.length ? sums.map((s) => {
        const a = byId(s.animalId) || {};
        const isOpen = open === s.animalId;
        const chips = s.flags.map((f) => `<span class="inline-block text-[11px] font-semibold px-2 py-0.5 rounded-full ${f.code === 'due' ? 'bg-amber-100 text-amber-800' : 'bg-red-100 text-red-700'}">${esc(f.text)}</span>`).join(' ');
        const hist = isOpen ? s.series.slice().reverse().map((p) => {
          const w = p.id ? all.find((x) => x.clientId === p.id) : null;
          const pending = w && w.syncStatus !== SYNC_STATUS.SYNCED;
          return `<tr class="border-t border-slate-100">
            <td class="py-1.5">${esc(fmt(p.date))}${a.dateOfBirth ? `<br><span class="text-[10px] text-slate-400">${esc(ageTxt(grwDays(a.dateOfBirth, p.date)))}</span>` : ''}</td>
            <td class="text-right font-semibold">${grwRound(p.kg, 1)}</td>
            <td class="text-right ${p.gain < 0 ? 'text-red-700' : ''}">${p.gain === null ? '' : (p.gain >= 0 ? '+' : '') + p.gain}</td>
            <td class="text-right">${p.days === null ? '' : p.days}</td>
            <td class="text-right">${p.adg === null ? '' : adgTxt(p.adg)}</td>
            <td class="text-right text-[11px] text-slate-500">${p.source === 'birth' ? 'calving record' : esc(p.method || '')}${pending ? '<br><span class="text-amber-700">not uploaded</span>' : w && w.corrected ? '<br><span class="text-amber-700">corrected</span>' : ''}</td>
            <td class="text-right">${w ? `<button type="button" class="gw-edit text-xs font-semibold text-calf-700 underline" data-cid="${esc(w.clientId)}">Edit</button>` : ''}</td>
          </tr>`;
        }).join('') : '';
        return `<li class="bg-white rounded-2xl shadow-sm">
          <button type="button" class="gw-card w-full text-left p-4" data-id="${esc(s.animalId)}" aria-expanded="${isOpen}">
            <div class="flex items-baseline justify-between gap-2">
              <p class="font-bold">${esc(s.name)} <span class="text-sm font-normal text-slate-400">${esc(s.animalId)}</span></p>
              <p class="text-lg font-bold text-calf-700">${s.latest ? kgs(s.latest.kg) : '—'}</p>
            </div>
            <p class="text-xs text-slate-500">${esc(a.category || '')}${a.breed ? ' · ' + esc(a.breed) : ''} · ${esc(ageTxt(s.ageDays))}${s.latest ? ` · weighed ${esc(fmt(s.latest.date))}` : ''}${s.birthKg ? ` · born ${kgs(s.birthKg)}` : ''}</p>
            <div class="grid grid-cols-3 gap-2 mt-2 text-center text-xs">
              <div class="rounded-lg bg-calf-50 py-1"><span class="text-slate-500">ADG latest</span><br><b>${s.adgLatest ? adgTxt(s.adgLatest.adg) : '—'}</b></div>
              <div class="rounded-lg bg-calf-50 py-1"><span class="text-slate-500">3 months</span><br><b>${s.adgRecent ? adgTxt(s.adgRecent.adg) : '—'}</b></div>
              <div class="rounded-lg bg-calf-50 py-1"><span class="text-slate-500">Since birth</span><br><b>${adgTxt(s.adgBirth)}</b></div>
            </div>
            <p class="text-[11px] text-slate-400 mt-1">kg/day · target ${s.target}</p>
            ${chips ? `<div class="mt-2 space-x-1 space-y-1">${chips}</div>` : ''}
          </button>
          ${isOpen ? `<div class="px-4 pb-4">${chart(s.series, s.target, a.dateOfBirth)}
            ${s.series.length ? `<table class="w-full text-xs mt-2"><thead><tr class="text-slate-500 text-right"><th class="text-left font-semibold">Date</th><th>kg</th><th>Gain</th><th>Days</th><th>kg/day</th><th>How</th><th></th></tr></thead><tbody>${hist}</tbody></table>`
              : '<p class="text-xs text-slate-400">No weights yet: add them in Weigh day above (any past date works).</p>'}
          </div>` : ''}
        </li>`;
      }).join('') : '<li class="text-sm text-slate-400 px-1">No calves or heifers in the herd register yet.</li>';
    }

    /* ================= edit ================= */

    function openEdit(clientId) {
      const w = weights().find((x) => x.clientId === clientId);
      if (!w) { toast('That weight is no longer here', 'error'); return; }
      editing = w;
      const synced = w.syncStatus === SYNC_STATUS.SYNCED;
      const a = byId(w.animalId) || {};
      $('#gw-edit-title').textContent = `Edit weight: ${a.name || w.animalName || w.animalId}`;
      $('#gw-edit-date').value = w.date;
      $('#gw-edit-date').max = todayLocal();
      if (a.dateOfBirth) $('#gw-edit-date').min = a.dateOfBirth; else $('#gw-edit-date').removeAttribute('min');
      $('#gw-edit-kg').value = w.weightKg;
      $('#gw-edit-method').value = METHODS.includes(w.method) ? w.method : 'Weigh band';
      $('#gw-edit-notes').value = w.notes || '';
      $('#gw-edit-reason').value = '';
      show($('#gw-edit-reason-wrap'), synced);
      $('#gw-edit-info').textContent = synced ? 'Already in Google Sheets: the sheet is corrected with the next sync, and the change is logged with your reason.' : 'Not uploaded yet: the entry on this phone is changed.';
      $('#gw-edit-void').textContent = synced ? 'Cancel this weight' : 'Delete this entry';
      setError('#gw-edit-error', '');
      show($('#gw-edit'), true);
      $('#gw-edit-kg').focus();
    }
    function closeEdit() { editing = null; show($('#gw-edit'), false); }

    /** The phone's own copy of a weight (a weight from another phone gets a local copy for its correction). */
    async function localCopy(w) {
      const l = await db[STORE].where('clientId').equals(w.clientId).first();
      if (l) return l;
      const { fromServer, ...rest } = w;
      const id = await db[STORE].add({ ...rest, syncStatus: SYNC_STATUS.SYNCED, syncAttempts: 0, lastError: null, syncedAt: w.updatedAt || w.createdAt || new Date().toISOString() });
      return db[STORE].get(id);
    }

    async function saveEdit(e) {
      e.preventDefault();
      if (!editing) return;
      setError('#gw-edit-error', '');
      const w = editing;
      const a = byId(w.animalId) || {};
      const date = $('#gw-edit-date').value;
      const kg = num($('#gw-edit-kg').value);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date > todayLocal()) { setError('#gw-edit-error', 'Pick the date (not in the future).'); return; }
      if (a.dateOfBirth && date < a.dateOfBirth) { setError('#gw-edit-error', `Born on ${fmt(a.dateOfBirth)}: pick a later date.`); return; }
      if (kg === null || kg < GRW_RULES.minKg || kg > GRW_RULES.maxKg) { setError('#gw-edit-error', `Weight must be ${GRW_RULES.minKg}–${GRW_RULES.maxKg} kg.`); return; }
      const changes = {};
      if (date !== w.date) changes.date = date;
      if (Math.abs(kg - Number(w.weightKg)) > 0.001) changes.weightKg = grwRound(kg, 1);
      if ($('#gw-edit-method').value !== w.method) changes.method = $('#gw-edit-method').value;
      const notes = $('#gw-edit-notes').value.trim().slice(0, 300);
      if (notes !== (w.notes || '')) changes.notes = notes;
      if (!Object.keys(changes).length) { closeEdit(); return; }
      const others = pointsFor(w.animalId).filter((p) => p.id !== w.clientId);
      const warn = grwCheckNew(others, date, kg);
      if (warn && !confirm(`${warn}\n\nSave anyway?`)) return;
      const now = new Date().toISOString();
      if (w.syncStatus !== SYNC_STATUS.SYNCED) {
        const l = await db[STORE].where('clientId').equals(w.clientId).first();
        if (!l) return;
        if (isInFlight && isInFlight(l.id)) { setError('#gw-edit-error', 'This weight is uploading right now. Try again in a moment.'); return; }
        await db[STORE].update(l.id, { ...changes, updatedAt: now });
        toast('Weight changed');
        closeEdit();
        return;
      }
      const reason = $('#gw-edit-reason').value.trim();
      if (!reason) { setError('#gw-edit-error', 'Give a reason for the change (it is kept with the record).'); return; }
      await queueCorrection({ sheet: 'Calf_Weights', id: w.clientId, changes, void: false, reason: reason.slice(0, 300) });
      const l = await localCopy(w);
      await db[STORE].update(l.id, { ...changes, corrected: true, updatedAt: now });
      toast('Changed: the sheet is corrected with the next sync');
      closeEdit();
    }

    async function voidEdit() {
      if (!editing) return;
      const w = editing;
      if (w.syncStatus !== SYNC_STATUS.SYNCED) {
        const l = await db[STORE].where('clientId').equals(w.clientId).first();
        if (!l) return;
        if (isInFlight && isInFlight(l.id)) { setError('#gw-edit-error', 'This weight is uploading right now. Try again in a moment.'); return; }
        if (!confirm('Delete this weight? It has not been uploaded yet.')) return;
        await db[STORE].delete(l.id);
        toast('Weight deleted', 'info');
        closeEdit();
        return;
      }
      const reason = $('#gw-edit-reason').value.trim();
      if (!reason) { setError('#gw-edit-error', 'Give a reason for cancelling (e.g. wrong animal).'); $('#gw-edit-reason').focus(); return; }
      if (!confirm(`Cancel the weight of ${grwRound(Number(w.weightKg), 1)} kg on ${fmt(w.date)}? It stays in the sheet marked Void and is no longer used.`)) return;
      await queueCorrection({ sheet: 'Calf_Weights', id: w.clientId, changes: {}, void: true, reason: reason.slice(0, 300) });
      const l = await localCopy(w);
      await db[STORE].update(l.id, { voided: true, updatedAt: new Date().toISOString() });
      toast('Weight cancelled: the sheet is updated with the next sync', 'info');
      closeEdit();
    }

    /* ================= server ================= */

    async function refresh(loud) {
      if (!navigator.onLine || !getSession()) { if (loud) toast('Updates when online and signed in', 'info'); return false; }
      try {
        const r = await callServer({ action: 'listGrowth' });
        if (!Array.isArray(r.weights)) throw new Error('reply has no weights');
        server = { weights: r.weights, births: r.births || [], rules: r.rules || null, serverTime: r.serverTime };
        await db.kv.put({ key: 'growthList', value: server });
        render();
        if (loud) toast('Weights updated', 'info');
        return true;
      } catch (err) {
        if (loud) toast('Could not update: ' + (err.message || err), 'error');
        return false;
      }
    }

    /* ================= init ================= */

    function init() {
      const t = todayLocal();
      $('#gw-date').value = t; $('#gw-date').max = t;
      $('#gw-method').innerHTML = METHODS.map((m) => `<option>${m}</option>`).join('');
      $('#gw-edit-method').innerHTML = METHODS.map((m) => `<option>${m}</option>`).join('');
      $$('.cv-view-btn').forEach((b) => b.addEventListener('click', () => setView(b.dataset.view)));
      $('#gw-form').addEventListener('submit', saveWeighDay);
      $('#gw-date').addEventListener('change', renderWeighRows);
      $('#gw-all').addEventListener('change', (e) => { showAll = e.target.checked; renderWeighRows(); });
      $('#gw-rows').addEventListener('input', (e) => { if (e.target.matches('input[data-id]')) hint(e.target); });
      $('#gw-refresh').addEventListener('click', () => refresh(true));
      $('#gw-animals').addEventListener('click', (e) => {
        const ed = e.target.closest('.gw-edit');
        if (ed) { openEdit(ed.dataset.cid); return; }
        const c = e.target.closest('.gw-card');
        if (c) { open = open === c.dataset.id ? null : c.dataset.id; render(); }
      });
      $('#gw-edit-form').addEventListener('submit', saveEdit);
      $('#gw-edit-void').addEventListener('click', voidEdit);
      $('#gw-edit-close').addEventListener('click', closeEdit);
      $('#gw-edit').addEventListener('click', (e) => { if (e.target.id === 'gw-edit') closeEdit(); });
      document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && editing) closeEdit(); });
      const watch = (q, set) => Dexie.liveQuery(q).subscribe({ next: (r) => { set(r); render(); }, error: (er) => console.error('Growth query failed:', er) });
      watch(() => db.animals.toArray(), (r) => { animals = r; });
      watch(() => db[STORE].toArray(), (r) => { local = r; });
      db.kv.get('growthList').then((x) => { if (x && x.value) { server = x.value; render(); } }).catch(() => {});
      setView('feed');
    }

    return Object.freeze({ init, refresh, render, openEdit });
  }

  window.MaweGrowth = Object.freeze({ create, STORE, PAYLOAD });
})();
